// THE UPDATE RUNNER (#768) — the shell that makes the versioned flows actually run
// against a member. Everything it decides was decided elsewhere: the flows judge and
// write, `terminalFor` says what happens to the PR, `deliveryFor` says whether the PR
// this run opens is the member's to land. What lives here is the I/O none of them may
// carry — the clone, the branch, the commit, the push, the PR, and the hand-off.
//
// SAME SHAPE AS BASELINING, deliberately. That worker is the proven pattern for
// "converge a member from its own Actions run": clone canon fresh, run the CLONE's
// scripts as subprocesses rather than the mount's stale copies, deliver on a branch,
// and let the shared landing helper own every nuance of arming versus merging. A
// second, cleverer shape here would be a second set of the same bugs.
//
// IT NO LONGER ASKS WHICH MECHANISM SERVES THE REPO. There is one, and its only
// rival was deleted in #768 Phase 5, so the question had exactly one answer for
// every member that could ask it; the `maintenance` block that held it is gone
// (#1252) and `engine/served-by.mjs` is deprecated with it.
import { execFileSync } from 'node:child_process';
import { readFileSync, existsSync, mkdtempSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { pathToFileURL } from 'node:url';
import { removeTree } from '../../../../engine/remove-tree.mjs';
import {
  deliveryFor, pullCreateError, landDelivery, openDeliveredPull, disposeOpenPull, withTaskTrailer,
} from '../../../claudinite-tasks/shared-code/delivery.mjs';
import { settingsPath, SETTINGS_FILE } from '../../../../engine/settings-file.mjs';

const CANON_URL = 'https://github.com/missingbulb/Claudinite.git'; // public — no token
const UPDATE_PREFIX = 'claudinite/update';
// What this worker stamps on everything it commits and merges (task-trailer.mjs).
const UPDATE_TASK_ID = 'claudinite-lifecycle/update';
const API = 'https://api.github.com';

const git = (args, opts = {}) =>
  execFileSync('git', args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], ...opts });

async function gh(token, path, { method = 'GET', body } = {}) {
  const res = await fetch(`${API}${path}`, {
    method,
    headers: {
      authorization: `Bearer ${token}`,
      accept: 'application/vnd.github+json',
      'x-github-api-version': '2022-11-28',
      ...(body ? { 'content-type': 'application/json' } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  let json = null;
  try { json = await res.json(); } catch { /* empty body */ }
  return { status: res.status, json };
}

// --- pure helpers (exported, unit-tested git-free) --------------------------

// One branch per run, dated and seeded like baselining's: two runs on one day must
// not collide, and a name that carries its date is one a human can read a week later.
// Minted only under an executor that hands no target in (DESIGN §6.4b) — see the
// tolerance in `main`, and #1698 for its removal.
export const updateBranchName = (day, seed) => `${UPDATE_PREFIX}-${day}-${seed}`;

// The line the LIVE CANARY rehearsal greps for. A rehearsal that converges nothing
// and exits 0 is worse than no gate at all — it reports a qualification that never
// happened — and that is not hypothetical: this exact gate went vacuous the day the
// canary flipped to `updates`, because the workflow drove the canary's baselining
// worker, which correctly stood down and exited 0 in zero seconds for weeks.
//
// So the rehearsal announces that it really ran, and the workflow fails when this
// line is absent. Any future path that skips the converge is caught by construction
// rather than by someone noticing a suspiciously fast green.
export const REHEARSAL_MARKER = 'claudinite-rehearsal: converged';

// The PR title and body for a terminal. The body is what a human reads when the run
// stopped, so it says WHICH terminal fired and why in its first line — a PR that only
// says "an update ran" makes every reader re-derive the thing the run already knew.
//
// THE TITLE IS A SUMMARY, THE BODY IS THE DETAIL. A title that names every moved pack
// grows with the number a member declares, and a PR list is where that is least
// readable — so the packs collapse to a count and only the engine keeps its versions.
export function updatePullText(terminal, { engine, packs }) {
  const engineMoved = engine?.from !== engine?.to;

// Technology stub pack: Android app development (Gradle/AGP, manifests, permissions, signing, flavors).
// Stub — no rules captured yet, so no RULES.md; durable, project-agnostic practices
// earn one as they are captured. Expected first source: missingbulb/ShoutsAndWhispers.
export default {
  version: '60903.1',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'gradle/AGP builds, AndroidManifest, permissions, signing configs, product flavors and emulator workflows for an Android app module',
    excludes: 'store submission and release cadence — play-store-release; Flutter-side widget or Dart code — flutter',
  },
  marker: 'android/app/src/main/AndroidManifest.xml',
  detect: (ctx) => ctx.tracked.some((f) => f.endsWith('android/app/src/main/AndroidManifest.xml')),
};

// Technology pack: a backend built on the Cloudflare Workers runtime and its
// bindings — D1, R2, Vectorize, Workflows, Workers AI, Containers — driven
// through Wrangler. The platform's own limits and deploy-window hazards, and
// the binding boundary that forces everything else into plain, fake-tested
// modules.
//
// Fingerprint: a wrangler config (toml, json, or jsonc) at the repo root or
// one directory down (a monorepo's backend/ or worker/ dir), but never
// deeper, so a stray one in a nested fixture or example tree can't trip
// detection.
const MARKERS = ['wrangler.toml', 'wrangler.json', 'wrangler.jsonc'];
const hasMarkerNearRoot = (ctx) =>
  ctx.tracked.some((f) => {
    const parts = f.split('/');
    return MARKERS.includes(parts[parts.length - 1]) && parts.length <= 2;
  });

export default {
  version: '60906.1',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'the Cloudflare Workers platform: Wrangler, D1, R2, Vectorize, Workflows, Workers AI and Containers',
    excludes: 'shipping a static site with no Worker — static-website; a different serverless vendor — aws-sam; generic Node conventions — node',
  },
  marker: 'a wrangler.toml/.json/.jsonc config (at the repo root or one directory down)',
  detect: hasMarkerNearRoot,
};

// Fingerprint: a package.json at the repo root OR one directory down (a
// monorepo's functions/ or server/ dir) — but never deeper, so a package.json
// in a nested fixture/example tree can't trip detection. (The jsdom gotchas in
// RULES.md stay prose — runtime divergence with no artifact signature.)
const hasMarkerNearRoot = (ctx, marker) =>
  ctx.tracked.some((f) => {
    const parts = f.split('/');
    return parts[parts.length - 1] === marker && parts.length <= 2;
  });

export default {
  version: '60906.2',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'conventions for a Node/npm project — module resolution, ESM vs CJS, dependency justification, jsdom test divergences',
    excludes: 'browser-runtime API behaviour — that is html or web-speech; Python packaging is python',
  },
  marker: 'package.json (at the repo root or one directory down)',
  detect: (ctx) => hasMarkerNearRoot(ctx, 'package.json'),
  // The Node runtime ships in the base image, but a repo's (often uncommitted,
  // devDependency) modules don't — so `npm test`/build would trigger a
  // confusing mid-session install. Install them at environment-image build. The
  // package.json location varies per repo, so it's a per-project param: set
  // `dirs` in the node pack entry's `config` in .claudinite-settings.json
  // (default: repo root). A
  // cloud setup script starts in the checkout's PARENT, so env.mjs runs this
  // from the checkout — the `cd "$d"` is relative to it.
  env: {
    label: 'Node dependencies (npm ci)',
    setup: (p) =>
      (p.dirs?.length ? p.dirs : ['.'])
        .map((d) => `( cd "${d}" && npm ci ) || true`)
        .join('\n'),
    probe: (p) =>
      (p.dirs?.length ? p.dirs : ['.'])
        .map((d) => `[ -d "${d}/node_modules" ]`)
        .join(' && '),
  },
};

// Prose + one environment requirement. Fingerprint: a pubspec.yaml at the repo
// root OR one directory down (a monorepo's app/ or client/ dir) — but never
// deeper, so a stray pubspec.yaml in a nested example/fixture tree can't trip
// detection.
const hasMarkerNearRoot = (ctx, marker) =>
  ctx.tracked.some((f) => {
    const parts = f.split('/');
    return parts[parts.length - 1] === marker && parts.length <= 2;
  });

export default {
  version: '60906.1',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'widget-tree architecture, ports and fakes, widget-test and golden mechanics, pub and analyze toolchain habits for Flutter',
    excludes: 'native Android or iOS module concerns — android and ios; store shipping — play-store-release, app-store-release',
  },
  marker: 'pubspec.yaml (at the repo root or one directory down)',
  detect: (ctx) => hasMarkerNearRoot(ctx, 'pubspec.yaml'),
  // The Flutter SDK isn't in the Claude Code Web base image, so a cloud session
  // can't run `flutter test` / analyze / golden regen without it. This declares
  // how the environment installs it (aggregated into environment-setup-command.sh) and
  // how the SessionStart check asserts it — see engine/pack_loader/env-requirements.mjs.
  env: {
    label: 'Flutter SDK',
    setup: [
      'if [ ! -x /opt/flutter/bin/flutter ]; then',
      '  git clone --depth 1 -b stable https://github.com/flutter/flutter.git /opt/flutter',
      'fi',
      'ln -sf /opt/flutter/bin/flutter /usr/local/bin/flutter',
      'ln -sf /opt/flutter/bin/dart /usr/local/bin/dart',
      'git config --global --add safe.directory /opt/flutter || true',
      'flutter --version || true',
      'flutter precache || true   # warm host engine artifacts so the first test is fast',
    ].join('\n'),
    probe: 'command -v flutter >/dev/null 2>&1',
  },
};

// Technology pack: iOS app development (Xcode project, Info.plist usage strings, entitlements, signing).
export default {
  version: '60906.1',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'app-target conventions for iOS — Xcode project, Info.plist usage strings, entitlements, code signing',
    excludes: 'shipping builds to the App Store — that is app-store-release; Android equivalents are android',
  },
  marker: 'ios/Runner/Info.plist',
  detect: (ctx) => ctx.tracked.some((f) => f.endsWith('ios/Runner/Info.plist')),
};

